contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool pauseFirst, uint256 dummy) public payable {
        require(dummy != 0 || !pauseFirst, "bad input");

        bool pausedBefore = c.paused();

        if (pauseFirst) {
            try c.pause() {} catch {}
        }

        bool pausedAfterSetup = c.paused();

        bool reverted;
        try c.pause() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool pausedAfter = c.paused();

        assert(!pausedAfterSetup || (reverted && pausedAfter == pausedAfterSetup && pausedAfter == pausedBefore));
    }
}

