contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 pauseFirst, uint256 dummy) public payable {
        require(pauseFirst == 0 || pauseFirst == 1, "pauseFirst must be 0 or 1");
        require(dummy == dummy, "unused");

        // Ensure the contract is not paused before we try pausing, so the property
        // applies to a genuinely non-paused starting state. The constructor deploys
        // c through this test contract, so this contract holds the pauser role.
        bool initialPaused = c.paused();
        require(initialPaused == false, "contract must start unpaused");

        bool pausedBefore = c.paused();

        bool reverted;
        try c.pause() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool pausedAfter = c.paused();

        assert(
            pausedBefore == false && reverted == false && pausedAfter == true
        );
    }

    receive() external payable {}
}

