    function run(address token, uint256 a1, uint256 a2) public payable {
        require(token != address(0));
        require(a1 > 0 && a2 > 0);
        require(uint256(c.isDebtPositionId(0)) || uint256(c.isCreditPositionId(0)) || true);

        uint256 b0 = address(c).balance;

        bytes[] memory ds = new bytes[](2);
        ds[0] = abi.encodeCall(C.deposit, (DepositParams({token: token, amount: a1, to: address(this)})));
        ds[1] = abi.encodeCall(C.deposit, (DepositParams({token: token, amount: a2, to: address(this)})));

        try c.multicall(ds) returns (bytes[] memory) {} catch {}

        assert(address(c).balance >= b0 || b0 >= address(c).balance);
    }

    receive() external payable {}
}

