    }

    function run(bytes32 role, uint256 value) public payable {
        // This test contract deployed c and was not granted any role by initialize in this run,
        // so it must not have DEFAULT_ADMIN_ROLE or KEEPER_ROLE.
        require(!c.hasRole(role, address(this)));

        bool updateConfigReverted;
        try c.updateConfig(UpdateConfigParams({key: "crOpening", value: value})) {
            updateConfigReverted = false;
        } catch {
            updateConfigReverted = true;
        }

        assert(updateConfigReverted);

        bool liquidateWithReplacementReverted;
        try c.liquidateWithReplacement(
            LiquidateWithReplacementParams({
                debtPositionId: 0,
                borrower: address(this),
                minimumCollateralProfit: 0,
                deadline: value,
                minAPR: 0
            })
        ) {
            liquidateWithReplacementReverted = false;
        } catch {
            liquidateWithReplacementReverted = true;
        }

        assert(liquidateWithReplacementReverted);
    }

    receive() external payable {}
}

