contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string memory key, uint256 value) public payable {
        require(!c.hasRole(0x00, address(this)));

        InitializeFeeConfigParams memory before = c.feeConfig();

        bool reverted;
        try c.updateConfig(UpdateConfigParams({key: key, value: value})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        InitializeFeeConfigParams memory afterConfig = c.feeConfig();

        assert(
            !reverted
                || (
                    afterConfig.swapFeeAPR == before.swapFeeAPR
                        && afterConfig.fragmentationFee == before.fragmentationFee
                        && afterConfig.liquidationRewardPercent == before.liquidationRewardPercent
                        && afterConfig.overdueCollateralProtocolPercent == before.overdueCollateralProtocolPercent
                        && afterConfig.collateralProtocolPercent == before.collateralProtocolPercent
                        && afterConfig.feeRecipient == before.feeRecipient
                )
        );
    }

    receive() external payable {}
}

